'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, stringify, CsvError } = require('../src/csv');

// Deterministic PRNG so failures are reproducible.
function mulberry32(seed) {
  return function next() {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function streamParse(chunks, options) {
  const parser = createParser(options);
  const records = [];
  for (const chunk of chunks) for (const record of parser.write(chunk)) records.push(record);
  for (const record of parser.end()) records.push(record);
  return records;
}

// Either the records or the error's identifying details.
function outcome(fn) {
  try {
    return { records: fn() };
  } catch (err) {
    return { error: { type: err.constructor.name, line: err.line, column: err.column, message: err.message } };
  }
}

function assertCsvError(fn, line, column) {
  assert.throws(fn, (err) => {
    assert.ok(err instanceof CsvError, `expected CsvError, got ${err && err.name}: ${err && err.message}`);
    assert.ok(err instanceof Error);
    assert.deepEqual({ line: err.line, column: err.column }, { line, column });
    return true;
  });
}

describe('parse', () => {
  it('rejects non-string input', () => {
    for (const value of [undefined, null, 1, {}, [], Buffer.from('a')]) {
      assert.throws(() => parse(value), TypeError);
    }
  });

  it('returns [] for empty input', () => {
    assert.deepEqual(parse(''), []);
  });

  it('parses simple records', () => {
    assert.deepEqual(parse('a,b,c\n1,2,3\n'), [
      ['a', 'b', 'c'],
      ['1', '2', '3'],
    ]);
    assert.deepEqual(parse('a,b,c'), [['a', 'b', 'c']]);
  });

  it('keeps empty fields', () => {
    assert.deepEqual(parse(',a,,\n'), [['', 'a', '', '']]);
    assert.deepEqual(parse('a,'), [['a', '']]);
    assert.deepEqual(parse(','), [['', '']]);
  });

  it('accepts CRLF, LF and CR, mixed in one input', () => {
    assert.deepEqual(parse('a\r\nb\nc\rd'), [['a'], ['b'], ['c'], ['d']]);
    assert.deepEqual(parse('a\r\n'), [['a']]);
    assert.deepEqual(parse('a\r'), [['a']]);
  });

  it('treats LF CR as two line breaks and CR CR LF as two line breaks', () => {
    assert.deepEqual(parse('a\n\rb'), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\r\r\nb'), [['a'], [''], ['b']]);
  });

  it('ignores one leading byte order mark', () => {
    assert.deepEqual(parse('﻿a,b'), [['a', 'b']]);
    assert.deepEqual(parse('﻿'), []);
    assert.deepEqual(parse('﻿﻿a'), [['﻿a']]);
    assert.deepEqual(parse('a,﻿b'), [['a', '﻿b']]);
    assert.deepEqual(parse('﻿a,b', { header: true }), []);
    assert.deepEqual(parse('﻿id\n1', { header: true }), [{ id: '1' }]);
  });

  it('parses quoted fields', () => {
    assert.deepEqual(parse('"a,b","c\r\nd","e\nf","g\rh"'), [['a,b', 'c\r\nd', 'e\nf', 'g\rh']]);
    assert.deepEqual(parse('"say ""hi""",""""'), [['say "hi"', '"']]);
    assert.deepEqual(parse('"",x'), [['', 'x']]);
    assert.deepEqual(parse('""'), [['']]);
    assert.deepEqual(parse('"a"\r\n"b"\n"c"\r"d"'), [['a'], ['b'], ['c'], ['d']]);
  });

  it('treats a quote that does not start the field as ordinary', () => {
    assert.deepEqual(parse('a"b,c""d,e"\n'), [['a"b', 'c""d', 'e"']]);
    assert.deepEqual(parse(' "a"'), [[' "a"']]);
  });

  it('never trims whitespace', () => {
    assert.deepEqual(parse(' a , b\t,\t\n'), [[' a ', ' b\t', '\t']]);
    assert.deepEqual(parse('" a "'), [[' a ']]);
  });

  it('does not start a record after one final line break', () => {
    assert.deepEqual(parse('a\n'), [['a']]);
    assert.deepEqual(parse('\n'), [['']]);
    assert.deepEqual(parse('a\n\n'), [['a'], ['']]);
    assert.deepEqual(parse('\r\n\r\n'), [[''], ['']]);
  });

  it('treats every other empty line as a record with one empty field', () => {
    assert.deepEqual(parse('a\n\nb\n\n\nc'), [['a'], [''], ['b'], [''], [''], ['c']]);
    assert.deepEqual(parse('\na'), [[''], ['a']]);
  });

  it('skips empty lines with skipEmptyLines', () => {
    const options = { skipEmptyLines: true };
    assert.deepEqual(parse('\n\na\r\n\r\n\rb\n\n', options), [['a'], ['b']]);
    assert.deepEqual(parse('\n', options), []);
    assert.deepEqual(parse('""\n\n,\n', options), [[''], ['', '']]);
    assert.deepEqual(parse(' \n', options), [[' ']]);
  });

  it('uses a custom delimiter', () => {
    assert.deepEqual(parse('a;b,c;"d;e"', { delimiter: ';' }), [['a', 'b,c', 'd;e']]);
    assert.deepEqual(parse('a\tb\n', { delimiter: '\t' }), [['a', 'b']]);
    assert.deepEqual(parse('a b  c', { delimiter: ' ' }), [['a', 'b', '', 'c']]);
  });

  it('validates the delimiter', () => {
    for (const delimiter of ['', ';;', '"', '\r', '\n', 1, null, ['x']]) {
      assert.throws(() => parse('a', { delimiter }), TypeError, `delimiter ${JSON.stringify(delimiter)}`);
    }
  });

  it('accepts a delimiter that also appears as a leading BOM', () => {
    assert.deepEqual(parse('﻿a﻿b', { delimiter: '﻿' }), [['a', 'b']]);
  });

  it('handles non-BMP characters', () => {
    assert.deepEqual(parse('😀,"a😀"'), [['😀', 'a😀']]);
  });

  describe('header mode', () => {
    it('returns objects keyed by the header', () => {
      assert.deepEqual(parse('name,age\r\nAda,36\r\nAlan,41\r\n', { header: true }), [
        { name: 'Ada', age: '36' },
        { name: 'Alan', age: '41' },
      ]);
    });

    it('returns [] for a header-only input', () => {
      assert.deepEqual(parse('a,b', { header: true }), []);
      assert.deepEqual(parse('a,b\n', { header: true }), []);
      assert.deepEqual(parse('', { header: true }), []);
    });

    it('rejects duplicate column names at the second occurrence', () => {
      assertCsvError(() => parse('a,b,a\n1,2,3', { header: true }), 1, 5);
      assertCsvError(() => parse('x,"a\nb","a\nb"', { header: true }), 2, 3);
      assertCsvError(() => parse(',', { header: true }), 1, 2);
      assertCsvError(() => parse('a,,', { header: true }), 1, 4);
      assertCsvError(() => parse('﻿a,a', { header: true }), 1, 3);
    });

    it('rejects records with the wrong number of fields', () => {
      assertCsvError(() => parse('a,b\n1,2\n1,2,3\n', { header: true }), 3, 1);
      assertCsvError(() => parse('a,b\n1', { header: true }), 2, 1);
      assertCsvError(() => parse('a,b\n"x\ny"\n', { header: true }), 2, 1);
      assertCsvError(() => parse('a,b\n1,2\n\n3,4', { header: true }), 3, 1);
    });

    it('treats empty lines as records unless skipEmptyLines is set', () => {
      assert.deepEqual(parse('a\n\nb\n', { header: true }), [{ a: '' }, { a: 'b' }]);
      assert.deepEqual(parse('\n\na,b\n\n1,2\n\n', { header: true, skipEmptyLines: true }), [{ a: '1', b: '2' }]);
      assert.deepEqual(parse('\nx\n', { header: true }), [{ '': 'x' }]);
    });

    it('sets __proto__ as an ordinary key', () => {
      const [record] = parse('__proto__,b\nx,y', { header: true });
      assert.equal(Object.getPrototypeOf(record), Object.prototype);
      assert.deepEqual(Object.keys(record), ['__proto__', 'b']);
      assert.equal(Object.getOwnPropertyDescriptor(record, '__proto__').value, 'x');
    });
  });

  describe('errors', () => {
    it('reports an unclosed quoted field at its opening quote', () => {
      assertCsvError(() => parse('"abc'), 1, 1);
      assertCsvError(() => parse('a,b\nc,"d\ne'), 2, 3);
      assertCsvError(() => parse('"a""'), 1, 1);
      assertCsvError(() => parse('﻿"'), 1, 1);
    });

    it('reports a character after a closing quote at that character', () => {
      assertCsvError(() => parse('"a"b'), 1, 4);
      assertCsvError(() => parse('x,"a" ,y'), 1, 6);
      assertCsvError(() => parse('a\n"b\r\nc"d'), 3, 3);
      assertCsvError(() => parse('"\r\r\n\n"x'), 4, 2);
      assertCsvError(() => parse('﻿"a"b'), 1, 4);
      assertCsvError(() => parse('"a"﻿'), 1, 4);
    });

    it('counts columns in UTF-16 code units', () => {
      assertCsvError(() => parse('😀,"a"b'), 1, 6);
    });

    it('throws the error a left-to-right read finds first', () => {
      // The duplicate header is known when its field ends, before the bad quote.
      assertCsvError(() => parse('a,a,"b"x', { header: true }), 1, 3);
      // A field count is checked when the record ends, after the bad quote.
      assertCsvError(() => parse('a\n1,"2"x', { header: true }), 2, 6);
      assertCsvError(() => parse('a\n1,2\n"3"x', { header: true }), 2, 1);
      assertCsvError(() => parse('a\n1,2\n"3', { header: true }), 2, 1);
      assertCsvError(() => parse('a\n"3', { header: true }), 2, 1);
    });

    it('is a subclass of Error with line and column', () => {
      const err = outcome(() => parse('"')).error;
      assert.equal(err.type, 'CsvError');
      assert.equal(err.line, 1);
      assert.equal(err.column, 1);
      const instance = new CsvError('msg', 2, 3);
      assert.ok(instance instanceof Error);
      assert.equal(instance.name, 'CsvError');
    });
  });
});

// Inputs that exercise every state transition, valid and invalid.
const CORPUS = [
  '',
  '﻿',
  '﻿a,b\r\nc',
  'a,b,c\r\n1,2,3\r\n',
