    const start = process.hrtime.bigint();
    parser.write('"');
    for (let k = 0; k < size; k++) parser.write(k % 1000 === 0 ? '\n' : 'x');
    parser.write('"');
    const [[field]] = parser.end();
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1e6;
