'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, stringify, CsvError } = require('../src/csv');

// Deterministic PRNG so failures are reproducible.
function mulberry32(seed) {
  return function next() {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function streamParse(chunks, options) {
  const parser = createParser(options);
  const records = [];
  for (const chunk of chunks) for (const record of parser.write(chunk)) records.push(record);
  for (const record of parser.end()) records.push(record);
  return records;
}

// Either the records or the error's identifying details.
function outcome(fn) {
  try {
    return { records: fn() };
  } catch (err) {
    return { error: { type: err.constructor.name, line: err.line, column: err.column, message: err.message } };
  }
}

function assertCsvError(fn, line, column) {
  assert.throws(fn, (err) => {
    assert.ok(err instanceof CsvError, `expected CsvError, got ${err && err.name}: ${err && err.message}`);
    assert.ok(err instanceof Error);
    assert.deepEqual({ line: err.line, column: err.column }, { line, column });
    return true;
  });
}

describe('parse', () => {
  it('rejects non-string input', () => {
    for (const value of [undefined, null, 1, {}, [], Buffer.from('a')]) {
      assert.throws(() => parse(value), TypeError);
    }
  });

  it('returns [] for empty input', () => {
    assert.deepEqual(parse(''), []);
  });

  it('parses simple records', () => {
    assert.deepEqual(parse('a,b,c\n1,2,3\n'), [
      ['a', 'b', 'c'],
      ['1', '2', '3'],
    ]);
    assert.deepEqual(parse('a,b,c'), [['a', 'b', 'c']]);
  });

  it('keeps empty fields', () => {
    assert.deepEqual(parse(',a,,\n'), [['', 'a', '', '']]);
    assert.deepEqual(parse('a,'), [['a', '']]);
    assert.deepEqual(parse(','), [['', '']]);
  });

  it('accepts CRLF, LF and CR, mixed in one input', () => {
    assert.deepEqual(parse('a\r\nb\nc\rd'), [['a'], ['b'], ['c'], ['d']]);
    assert.deepEqual(parse('a\r\n'), [['a']]);
    assert.deepEqual(parse('a\r'), [['a']]);
  });

  it('treats LF CR as two line breaks and CR CR LF as two line breaks', () => {
    assert.deepEqual(parse('a\n\rb'), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\r\r\nb'), [['a'], [''], ['b']]);
  });

  it('ignores one leading byte order mark', () => {
    assert.deepEqual(parse('﻿a,b'), [['a', 'b']]);
    assert.deepEqual(parse('﻿'), []);
    assert.deepEqual(parse('﻿﻿a'), [['﻿a']]);
    assert.deepEqual(parse('a,﻿b'), [['a', '﻿b']]);
    assert.deepEqual(parse('﻿a,b', { header: true }), []);
    assert.deepEqual(parse('﻿id\n1', { header: true }), [{ id: '1' }]);
  });

  it('parses quoted fields', () => {
    assert.deepEqual(parse('"a,b","c\r\nd","e\nf","g\rh"'), [['a,b', 'c\r\nd', 'e\nf', 'g\rh']]);
    assert.deepEqual(parse('"say ""hi""",""""'), [['say "hi"', '"']]);
    assert.deepEqual(parse('"",x'), [['', 'x']]);
    assert.deepEqual(parse('""'), [['']]);
    assert.deepEqual(parse('"a"\r\n"b"\n"c"\r"d"'), [['a'], ['b'], ['c'], ['d']]);
  });

  it('treats a quote that does not start the field as ordinary', () => {
    assert.deepEqual(parse('a"b,c""d,e"\n'), [['a"b', 'c""d', 'e"']]);
    assert.deepEqual(parse(' "a"'), [[' "a"']]);
  });

  it('never trims whitespace', () => {
    assert.deepEqual(parse(' a , b\t,\t\n'), [[' a ', ' b\t', '\t']]);
    assert.deepEqual(parse('" a "'), [[' a ']]);
  });

  it('does not start a record after one final line break', () => {
    assert.deepEqual(parse('a\n'), [['a']]);
    assert.deepEqual(parse('\n'), [['']]);
    assert.deepEqual(parse('a\n\n'), [['a'], ['']]);
    assert.deepEqual(parse('\r\n\r\n'), [[''], ['']]);
  });

  it('treats every other empty line as a record with one empty field', () => {
    assert.deepEqual(parse('a\n\nb\n\n\nc'), [['a'], [''], ['b'], [''], [''], ['c']]);
    assert.deepEqual(parse('\na'), [[''], ['a']]);
  });

  it('skips empty lines with skipEmptyLines', () => {
    const options = { skipEmptyLines: true };
    assert.deepEqual(parse('\n\na\r\n\r\n\rb\n\n', options), [['a'], ['b']]);
    assert.deepEqual(parse('\n', options), []);
    assert.deepEqual(parse('""\n\n,\n', options), [[''], ['', '']]);
    assert.deepEqual(parse(' \n', options), [[' ']]);
  });

  it('uses a custom delimiter', () => {
    assert.deepEqual(parse('a;b,c;"d;e"', { delimiter: ';' }), [['a', 'b,c', 'd;e']]);
    assert.deepEqual(parse('a\tb\n', { delimiter: '\t' }), [['a', 'b']]);
    assert.deepEqual(parse('a b  c', { delimiter: ' ' }), [['a', 'b', '', 'c']]);
  });

  it('validates the delimiter', () => {
    for (const delimiter of ['', ';;', '"', '\r', '\n', 1, null, ['x']]) {
      assert.throws(() => parse('a', { delimiter }), TypeError, `delimiter ${JSON.stringify(delimiter)}`);
    }
  });

  it('accepts a delimiter that also appears as a leading BOM', () => {
    assert.deepEqual(parse('﻿a﻿b', { delimiter: '﻿' }), [['a', 'b']]);
  });

  it('handles non-BMP characters', () => {
    assert.deepEqual(parse('😀,"a😀"'), [['😀', 'a😀']]);
  });

  describe('header mode', () => {
    it('returns objects keyed by the header', () => {
      assert.deepEqual(parse('name,age\r\nAda,36\r\nAlan,41\r\n', { header: true }), [
        { name: 'Ada', age: '36' },
        { name: 'Alan', age: '41' },
      ]);
    });

    it('returns [] for a header-only input', () => {
      assert.deepEqual(parse('a,b', { header: true }), []);
      assert.deepEqual(parse('a,b\n', { header: true }), []);
      assert.deepEqual(parse('', { header: true }), []);
    });

    it('rejects duplicate column names at the second occurrence', () => {
      assertCsvError(() => parse('a,b,a\n1,2,3', { header: true }), 1, 5);
      assertCsvError(() => parse('x,"a\nb","a\nb"', { header: true }), 2, 3);
      assertCsvError(() => parse(',', { header: true }), 1, 2);
      assertCsvError(() => parse('a,,', { header: true }), 1, 4);
      assertCsvError(() => parse('﻿a,a', { header: true }), 1, 3);
    });

    it('rejects records with the wrong number of fields', () => {
      assertCsvError(() => parse('a,b\n1,2\n1,2,3\n', { header: true }), 3, 1);
      assertCsvError(() => parse('a,b\n1', { header: true }), 2, 1);
      assertCsvError(() => parse('a,b\n"x\ny"\n', { header: true }), 2, 1);
      assertCsvError(() => parse('a,b\n1,2\n\n3,4', { header: true }), 3, 1);
    });

    it('treats empty lines as records unless skipEmptyLines is set', () => {
      assert.deepEqual(parse('a\n\nb\n', { header: true }), [{ a: '' }, { a: 'b' }]);
      assert.deepEqual(parse('\n\na,b\n\n1,2\n\n', { header: true, skipEmptyLines: true }), [{ a: '1', b: '2' }]);
      assert.deepEqual(parse('\nx\n', { header: true }), [{ '': 'x' }]);
    });

    it('sets __proto__ as an ordinary key', () => {
      const [record] = parse('__proto__,b\nx,y', { header: true });
      assert.equal(Object.getPrototypeOf(record), Object.prototype);
      assert.deepEqual(Object.keys(record), ['__proto__', 'b']);
      assert.equal(Object.getOwnPropertyDescriptor(record, '__proto__').value, 'x');
    });
  });

  describe('errors', () => {
    it('reports an unclosed quoted field at its opening quote', () => {
      assertCsvError(() => parse('"abc'), 1, 1);
      assertCsvError(() => parse('a,b\nc,"d\ne'), 2, 3);
      assertCsvError(() => parse('"a""'), 1, 1);
      assertCsvError(() => parse('﻿"'), 1, 1);
    });

    it('reports a character after a closing quote at that character', () => {
      assertCsvError(() => parse('"a"b'), 1, 4);
      assertCsvError(() => parse('x,"a" ,y'), 1, 6);
      assertCsvError(() => parse('a\n"b\r\nc"d'), 3, 3);
      assertCsvError(() => parse('"\r\r\n\n"x'), 4, 2);
      assertCsvError(() => parse('﻿"a"b'), 1, 4);
      assertCsvError(() => parse('"a"﻿'), 1, 4);
    });

    it('counts columns in UTF-16 code units', () => {
      assertCsvError(() => parse('😀,"a"b'), 1, 6);
    });

    it('throws the error a left-to-right read finds first', () => {
      // The duplicate header is known when its field ends, before the bad quote.
      assertCsvError(() => parse('a,a,"b"x', { header: true }), 1, 3);
      // A field count is checked when the record ends, after the bad quote.
      assertCsvError(() => parse('a\n1,"2"x', { header: true }), 2, 6);
      assertCsvError(() => parse('a\n1,2\n"3"x', { header: true }), 2, 1);
      assertCsvError(() => parse('a\n1,2\n"3', { header: true }), 2, 1);
      assertCsvError(() => parse('a\n"3', { header: true }), 2, 1);
    });

    it('is a subclass of Error with line and column', () => {
      const err = outcome(() => parse('"')).error;
      assert.equal(err.type, 'CsvError');
      assert.equal(err.line, 1);
      assert.equal(err.column, 1);
      const instance = new CsvError('msg', 2, 3);
      assert.ok(instance instanceof Error);
      assert.equal(instance.name, 'CsvError');
    });
  });
});

// Inputs that exercise every state transition, valid and invalid.
const CORPUS = [
  '',
  '﻿',
  '﻿a,b\r\nc',
  'a,b,c\r\n1,2,3\r\n',
  'a\rb\nc\r\nd',
  '\r\n\r\n',
  '\r\r\n\n\r',
  'a\n\n\nb\n',
  '"a,b","c""d",e\r\n',
  '"line\r\nbreak","cr\ronly","lf\nonly"\n',
  '"""",""""""\r\n""',
  'a"b,"c"\r\n',
  ',,\n,',
  ' x , y ',
  '"abc',
  '"a"b',
  'x,"a\r\nb"c',
  'a,"b""\r\n',
  'h1,h2\r\n1,2\r\n3,4',
  'h1,h1\r\n1,2',
  'h1,h2\r\n1\r\n',
  'h1,h2\r\n\r\n1,2',
  'h\n"a"x\n1,2',
  '😀,"😀\r\n"',
];

describe('createParser', () => {
  it('validates options up front', () => {
    assert.throws(() => createParser({ delimiter: ',,' }), TypeError);
  });

  it('returns each record from the write whose chunk ends it', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a,b'), []);
    assert.deepEqual(parser.write('\nc,d\ne'), [
      ['a', 'b'],
      ['c', 'd'],
    ]);
    assert.deepEqual(parser.write(',f\r'), [['e', 'f']]);
    assert.deepEqual(parser.write('\n'), []);
    assert.deepEqual(parser.write('g'), []);
    assert.deepEqual(parser.end(), [['g']]);
  });

  it('handles a CRLF split across chunks', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.write('\nb\r'), [['b']]);
    assert.deepEqual(parser.write('\r'), [['']]);
    assert.deepEqual(parser.write('\n'), []);
    assert.deepEqual(parser.end(), []);
  });

  it('handles an escaped quote split across chunks', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('"a"'), []);
    assert.deepEqual(parser.write('"b"'), []);
    assert.deepEqual(parser.write('\n'), [['a"b']]);
    assert.deepEqual(parser.end(), []);
  });

  it('ignores a BOM that arrives after empty chunks', () => {
    assert.deepEqual(streamParse(['', '', '﻿a'], {}), [['a']]);
    assert.deepEqual(streamParse(['a', '﻿'], {}), [['a﻿']]);
  });

  it('supports header mode', () => {
    const parser = createParser({ header: true });
    assert.deepEqual(parser.write('x,y\n1,'), []);
    assert.deepEqual(parser.write('2\n3,4'), [{ x: '1', y: '2' }]);
    assert.deepEqual(parser.end(), [{ x: '3', y: '4' }]);
  });

  it('matches parse for every way of splitting the input in two or three', () => {
    for (const options of [{}, { skipEmptyLines: true }, { header: true }, { header: true, skipEmptyLines: true }]) {
      for (const input of CORPUS) {
        const expected = outcome(() => parse(input, options));
        const n = input.length;
        for (let i = 0; i <= n; i++) {
          for (let j = i; j <= n; j++) {
            const chunks = [input.slice(0, i), input.slice(i, j), input.slice(j)];
            assert.deepEqual(
              outcome(() => streamParse(chunks, options)),
              expected,
              `input ${JSON.stringify(input)} split ${JSON.stringify(chunks)} options ${JSON.stringify(options)}`
            );
          }
        }
      }
    }
  });

  it('matches parse when fed one character at a time', () => {
    for (const input of CORPUS) {
      for (const options of [{}, { header: true }, { skipEmptyLines: true, delimiter: ';' }]) {
        assert.deepEqual(outcome(() => streamParse(input.split(''), options)), outcome(() => parse(input, options)));
      }
    }
  });

  it('matches parse on random inputs and random chunkings', () => {
    const random = mulberry32(42);
    const alphabet = ['a', 'b', ',', '"', '"', '\r', '\n', ' ', '﻿'];
    for (let round = 0; round < 3000; round++) {
      let input = '';
      const length = Math.floor(random() * 20);
      for (let k = 0; k < length; k++) input += alphabet[Math.floor(random() * alphabet.length)];
      const chunks = [];
      for (let start = 0; start < input.length; ) {
        const size = Math.floor(random() * 5);
        chunks.push(input.slice(start, start + size));
        start += size;
      }
      const options = { header: random() < 0.3, skipEmptyLines: random() < 0.5 };
      assert.deepEqual(
        outcome(() => streamParse(chunks, options)),
        outcome(() => parse(input, options)),
        `chunks ${JSON.stringify(chunks)} options ${JSON.stringify(options)}`
      );
    }
  });

  it('rejects non-string chunks and then stays finished', () => {
    const parser = createParser();
    assert.throws(() => parser.write(Buffer.from('a')), TypeError);
    assert.throws(() => parser.write('a'), (err) => err instanceof Error && !(err instanceof CsvError));
    assert.throws(() => parser.end(), Error);
  });

  it('throws after end()', () => {
    const parser = createParser();
    parser.write('a');
    assert.deepEqual(parser.end(), [['a']]);
    assert.throws(() => parser.write('b'), Error);
    assert.throws(() => parser.end(), Error);
  });

  it('throws after a CsvError from write or end', () => {
    const parser = createParser();
    assert.throws(() => parser.write('"a"b'), CsvError);
    assert.throws(() => parser.write('\n'), Error);
    assert.throws(() => parser.end(), Error);

    const unclosed = createParser();
    unclosed.write('"a');
    assert.throws(() => unclosed.end(), CsvError);
    assert.throws(() => unclosed.end(), Error);
    assert.throws(() => unclosed.write(''), Error);
  });

  it('stays linear when a large field arrives one character at a time', () => {
    const size = 200000;
    const parser = createParser();
    const start = process.hrtime.bigint();
    parser.write('"');
    for (let k = 0; k < size; k++) parser.write(k % 1000 === 0 ? '\n' : 'x');
    parser.write('"');
    const [[field]] = parser.end();
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1e6;
    assert.equal(field.length, size);
    assert.ok(elapsedMs < 5000, `took ${elapsedMs}ms`);
  });
});

describe('stringify', () => {
  it('writes records joined by CRLF with a final CRLF', () => {
    assert.equal(
      stringify([
        ['a', 'b'],
        ['c', 'd'],
      ]),
      'a,b\r\nc,d\r\n'
    );
  });

  it('returns an empty string for no rows', () => {
    assert.equal(stringify([]), '');
  });

  it('converts values', () => {
    assert.equal(stringify([['s', 1, 2.5, -0, true, false, null, undefined]]), 's,1,2.5,0,true,false,,\r\n');
    assert.equal(stringify([[NaN, Infinity]]), 'NaN,Infinity\r\n');
  });

  it('rejects other value types', () => {
    for (const value of [{}, [], () => {}, Symbol('x'), 1n, new Date(0), new String('s')]) {
      assert.throws(() => stringify([[value]]), TypeError);
    }
  });

  it('rejects non-array rows and records', () => {
    assert.throws(() => stringify('a'), TypeError);
    assert.throws(() => stringify(null), TypeError);
    assert.throws(() => stringify(['a']), TypeError);
    assert.throws(() => stringify([{ a: 1 }]), TypeError);
    assert.throws(() => stringify([null]), TypeError);
  });

  it('quotes fields that need it', () => {
    assert.equal(stringify([['a,b', 'q"q', 'c\rr', 'l\nf', ' lead', 'trail ', 'mid dle', 'plain']]),
      '"a,b","q""q","c\rr","l\nf"," lead","trail ",mid dle,plain\r\n');
    assert.equal(stringify([['"']]), '""""\r\n');
    assert.equal(stringify([[' ']]), '" "\r\n');
    assert.equal(stringify([['\ttab\t']]), '\ttab\t\r\n');
  });

  it('writes a lone empty field as ""', () => {
    assert.equal(stringify([[''], ['', ''], ['a']]), '""\r\n,\r\na\r\n');
    assert.equal(stringify([[null]]), '""\r\n');
  });

  it('writes an empty record as an empty line', () => {
    assert.equal(stringify([[], ['a']]), '\r\na\r\n');
  });

  it('supports eol', () => {
    assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
    assert.equal(stringify([['a']], { eol: '\r\n' }), 'a\r\n');
    for (const eol of ['\r', '', ';', null, 1]) {
      assert.throws(() => stringify([['a']], { eol }), TypeError, `eol ${JSON.stringify(eol)}`);
    }
  });

  it('supports and validates delimiter', () => {
    assert.equal(stringify([['a;b', 'c,d', 'e']], { delimiter: ';' }), '"a;b";c,d;e\r\n');
    assert.equal(stringify([['a\tb', 'c']], { delimiter: '\t' }), '"a\tb"\tc\r\n');
    for (const delimiter of ['', ';;', '"', '\r', '\n', 1]) {
      assert.throws(() => stringify([['a']], { delimiter }), TypeError);
    }
  });

  it('writes objects in header order', () => {
    const rows = [
      { name: 'Ada', age: 36, extra: 'ignored' },
      { age: 41 },
      ['x', 'y'],
    ];
    assert.equal(stringify(rows, { header: ['name', 'age'] }), 'name,age\r\nAda,36\r\n,41\r\nx,y\r\n');
    assert.equal(stringify([{ toString: 'x' }, {}], { header: ['toString'] }), 'toString\r\nx\r\n""\r\n');
  });

  it('writes the header row even with no rows', () => {
    assert.equal(stringify([], { header: ['a', 'b'] }), 'a,b\r\n');
  });

  it('quotes header names like other fields', () => {
    assert.equal(stringify([{ 'a,b': 1 }], { header: ['a,b'] }), '"a,b"\r\n1\r\n');
  });

  it('validates header', () => {
    assert.throws(() => stringify([], { header: 'a' }), TypeError);
    assert.throws(() => stringify([], { header: [1] }), TypeError);
    assert.throws(() => stringify([], { header: true }), TypeError);
  });

  it('quotes a BOM at the very start of the output', () => {
    assert.equal(stringify([['﻿a', '﻿b'], ['﻿c']]), '"﻿a",﻿b\r\n﻿c\r\n');
    assert.equal(stringify([['', 'a']], { delimiter: '﻿' }), '""﻿a\r\n');
  });
});

describe('round trip', () => {
  it('preserves known tricky rows', () => {
    const rows = [
      [''],
      ['', ''],
      [' '],
      ['"'],
      ['\r', '\n', '\r\n', '\n\r'],
      ['﻿'],
      ['a,b', 'c"d', ' e ', 'f'],
      ['😀', '\ud800'],
    ];
    for (const options of [{}, { skipEmptyLines: true }, { eol: '\n' }, { delimiter: ';', eol: '\n', skipEmptyLines: true }]) {
      assert.deepEqual(parse(stringify(rows, options), options), rows);
    }
  });

  it('preserves random rows', () => {
    const random = mulberry32(7);
    const alphabet = ['a', 'Z', ' ', ',', ';', '\t', '"', '\r', '\n', '﻿', 'é', '😀', '|'];
    const delimiters = [',', ';', '\t', ' ', '|', '﻿', 'a'];
    for (let round = 0; round < 3000; round++) {
      const rows = [];
      const rowCount = Math.floor(random() * 5);
      for (let r = 0; r < rowCount; r++) {
        const row = [];
        const fieldCount = 1 + Math.floor(random() * 4);
        for (let f = 0; f < fieldCount; f++) {
          let field = '';
          const length = Math.floor(random() * 6);
          for (let k = 0; k < length; k++) field += alphabet[Math.floor(random() * alphabet.length)];
          row.push(field);
        }
        rows.push(row);
      }
      const options = {
        delimiter: delimiters[Math.floor(random() * delimiters.length)],
        eol: random() < 0.5 ? '\r\n' : '\n',
        skipEmptyLines: random() < 0.5,
      };
      const text = stringify(rows, options);
      const message = `rows ${JSON.stringify(rows)} options ${JSON.stringify(options)}`;
      assert.deepEqual(parse(text, options), rows, message);
      assert.deepEqual(streamParse(text.split(''), options), rows, message);
    }
  });

  it('preserves objects through header mode', () => {
    const header = ['id', 'note', ''];
    const rows = [
      { id: '1', note: 'hello, "world"', '': 'x' },
      { id: '2', note: 'multi\r\nline', '': '' },
    ];
    assert.deepEqual(parse(stringify(rows, { header }), { header: true }), rows);
  });
});

