feed(s) {
  const n = s.length;
  if (n === 0) return;
  let i = 0;
  if (!this.started) {
    this.started = true;
    if (s.charCodeAt(0) === BOM) i = 1;
  }
  const delimiter = this.delimiter;

  while (i < n) {
    const c = s.charCodeAt(i);
    switch (this.state) {
      case RECORD_START:
        if (this.afterCR) {
          this.afterCR = false;
          if (c === LF) {
            i++;
            continue;
          }
        }
        if (this.skipEmptyLines && (c === CR || c === LF)) {
          i++;
          this.newline(c);
          continue;
        }
        this.recordLine = this.line;
        this.state = FIELD_START;
      // falls through
      case FIELD_START:
        this.fieldLine = this.line;
        this.fieldCol = this.col;
        if (c === QUOTE) {
          i++;
          this.col++;
          this.state = QUOTED;
          continue;
        }
        if (c === delimiter) {
          i++;
          this.col++;
          this.endField();
          continue;
        }
        if (c === CR || c === LF) {
          i++;
          this.newline(c);
          this.endField();
          this.endRecord();
          continue;
        }
        this.state = UNQUOTED;
      // falls through
      case UNQUOTED: {
        let j = i;
        while (j < n) {
          const d = s.charCodeAt(j);
          if (d === delimiter || d === CR || d === LF) break;
          j++;
        }
